from pathlib import Path
import base64
import sys

TARGET = Path("public/index.html")
MARKER = "HM_MENU_COMPANY_FINANCIALS_V1"
BLOCK = base64.b64decode(" ").decode("utf-8")

text = TARGET.read_text(encoding="utf-8")
if MARKER in text:
    print("Menu + Company Financials patch already present; no changes needed.")
    sys.exit(0)

closing = text.rfind("</body>")
if closing < 0:
    raise SystemExit("Could not find </body> in public/index.html")

updated = text[:closing] + "\n" + BLOCK + "\n" + text[closing:]
if updated.count(MARKER) != 1:
    raise SystemExit("Patch marker validation failed")

TARGET.write_text(updated, encoding="utf-8")
print("Inserted Hail Money menu reorder + Company Financials patch.")
